import { Chess } from 'chess.js';

// Opening repertoires for the opening trainer. This is fixed, hand-written theory (move
// orders and the ideas behind them), not engine output and not generated by Claude.
// Each line is a list of [SAN move, why] pairs from the starting position. Lines are merged
// into one book keyed by position, so transpositions between lines are recognised.

type Line = [san: string, why: string][];

export interface SetupItem {
  label: string; // e.g. "Bishop to f4"
  done: (g: Chess) => boolean;
}

export interface Opening {
  id: string;
  name: string;
  side: 'white' | 'black';
  summary: string;
  plans: string; // what to aim for once the book runs out
  setup: SetupItem[];
  lines: Line[]; // the first line is the main line
}

const piece = (g: Chess, sq: string, type: string, color: 'w' | 'b') => {
  const p = g.get(sq as Parameters<Chess['get']>[0]);
  return p?.type === type && p.color === color;
};
const anyOf = (g: Chess, squares: string[], type: string, color: 'w' | 'b') => squares.some((s) => piece(g, s, type, color));

