export const OPENINGS: Opening[] = [LONDON, DRAGON];

// ---------------------------------------------------------------------------------------
// Book lookup
// ---------------------------------------------------------------------------------------

export interface BookMove {
  san: string;
  why: string;
  weight: number; // for choosing Stockfish's book replies: main line 3, others 1
}

/** Position key without move counters, so transpositions match. */
export const positionKey = (fen: string) => fen.split(' ').slice(0, 4).join(' ');

/** Merges an opening's lines into position -> book moves. Throws on an illegal book move. */
export function buildBook(opening: Opening): Map<string, BookMove[]> {
  const book = new Map<string, BookMove[]>();
  opening.lines.forEach((line, lineIndex) => {
    const g = new Chess();
    for (const [san, why] of line) {
      const key = positionKey(g.fen());
      const move = g.move(san); // throws if the book has an illegal move
      const moves = book.get(key) ?? [];
      const existing = moves.find((m) => m.san === move.san);
      if (!existing) moves.push({ san: move.san, why, weight: lineIndex === 0 ? 3 : 1 });
      else if (!existing.why && why) existing.why = why;
      book.set(key, moves);
    }
  });
  return book;
}

const books = new Map(OPENINGS.map((o) => [o.id, buildBook(o)]));
export const bookFor = (id: string) => books.get(id)!;
export const openingById = (id: string | null) => OPENINGS.find((o) => o.id === id) ?? null;

export interface PlayedMove {
  ply: number;
  san: string;
  side: 'white' | 'black';
  inBook: boolean;
  why: string | null;
}

export interface BookStatus {
  played: PlayedMove[];
  // The first move that was not in the book, if any.
  leftAt: { ply: number; by: 'you' | 'opponent'; san: string; bookMoves: string[] } | null;
  // Book moves in the current position (empty when out of book or at the end of a line).
  next: BookMove[];
  nextSide: 'white' | 'black';
}

/** Where the game stands against the opening book. */
export function bookStatus(opening: Opening, history: string[], myColor: 'white' | 'black'): BookStatus {
  const book = bookFor(opening.id);
  const g = new Chess();
  const played: PlayedMove[] = [];
  let leftAt: BookStatus['leftAt'] = null;
  history.forEach((san, ply) => {
    const options = book.get(positionKey(g.fen())) ?? [];
    const side = g.turn() === 'w' ? 'white' : 'black';
    const hit = options.find((m) => m.san === san);
    if (!hit && !leftAt) {
      leftAt = { ply, by: side === myColor ? 'you' : 'opponent', san, bookMoves: options.map((m) => m.san) };
    }
    played.push({ ply, san, side, inBook: !!hit && !leftAt, why: hit?.why || null });
    g.move(san);
  });
  // A transposition can bring the game back into the book, so look the position up directly.
  const next = book.get(positionKey(g.fen())) ?? [];
  return { played, leftAt, next, nextSide: g.turn() === 'w' ? 'white' : 'black' };
}

/** Picks one of the book's replies for Stockfish, weighted toward the main line. */
export function pickBookReply(moves: BookMove[], random = Math.random): BookMove | null {
  if (moves.length === 0) return null;
  const total = moves.reduce((s, m) => s + m.weight, 0);
  let r = random() * total;
  for (const m of moves) {
    r -= m.weight;
    if (r < 0) return m;
  }
  return moves[moves.length - 1];
}

/** One line for the coach describing the opening practice, or null if none is selected. */
/**
 * Context for the coach: what the student is practising, where the game stands against the
 * book, and the repertoire's own explanations for the last few book moves and the next ones,
 * so the coach teaches from the prepared ideas rather than from memory. Null if no opening
 * is being practised with this colour.
 */
export function openingContext(opening: Opening | null, history: string[], myColor: 'white' | 'black'): string | null {
  if (!opening) return null;
  if (opening.side !== myColor) return null;
  const s = bookStatus(opening, history, myColor);
  const label = (ply: number, san: string) => `${Math.floor(ply / 2) + 1}${ply % 2 === 0 ? '.' : '...'}${san}`;
  const parts = [`The student is practising the ${opening.name} (as ${opening.side}).`];

  const recentBook = s.played.filter((m) => m.inBook && m.why).slice(-3);
  if (recentBook.length) {
    parts.push(`Ideas behind the last book moves: ${recentBook.map((m) => `${label(m.ply, m.san)}: ${m.why}`).join(' ')}`);
  }
  if (s.leftAt) {
    const book = s.leftAt.bookMoves.length ? ` (the book had ${s.leftAt.bookMoves.join(' or ')})` : '';
    const who = s.leftAt.by === 'you' ? 'The student' : 'The engine';
    parts.push(`${who} left the prepared line with ${label(s.leftAt.ply, s.leftAt.san)}${book}.`, `Typical plans: ${opening.plans}`);
  } else if (s.next.length === 0 && history.length > 0) {
    parts.push('The prepared line has ended.', `Typical plans: ${opening.plans}`);
  } else if (s.next.length) {
    const whose = s.nextSide === myColor ? "The student's book move" : 'Book replies for the engine';
    parts.push(`${whose} next: ${s.next.slice(0, 3).map((m) => `${label(history.length, m.san)}: ${m.why}`).join(' ')}`);
  }
  return parts.join(' ').replace(/Typical plans: Typical plans:/g, 'Typical plans:');
}
